#[test]
fn tri_stiff_matches_derivation_skew_complex() {
    let owners = tri_dof_owners(&[2; 3], 2);
    let got = tri_stiff(&owners, &V_skew_complex, C64::new(1.50000000000000000e+00, -6.99999999999999956e-01));
    let err = maxdiff(&got, &M_skew_complex);
    eprintln!("skew_complex: max rel err {:.2e}", err);
    assert!(err < 1e-10, "mismatch (skew_complex): {:.2e}", err);
}
